/**
 * Controller for the Release Relay tab: connect, select (org changes, deletions, manual items,
 * or an existing branch), review, and raise a GitHub pull request into this org's next branch.
 * Logic lives here and in the LWC JS; there are no triggers.
 */
public with sharing class RlyReleaseController {

    private static final Set<String> OPEN_STATUSES = new Set<String>{
        'Submitted', 'Workflow running', 'Retrieving', 'Validating', 'PR open', 'Checks failed', 'Ready for approval', 'Approved', 'Merging', 'Deploying'
    };
    private static final Set<String> FAILED_STATUSES = new Set<String>{ 'Failed', 'Checks failed', 'Deploy failed' };
    private static final Set<String> CHANGE_TYPES = new Set<String>{ 'New', 'Modified', 'Deleted' };
    private static final Pattern ITEM_TYPE = Pattern.compile('^[A-Za-z]{2,80}$');
    private static final Integer MAX_INPUT_CHARS = 60000;

    public class ItemInput {
        public String metadataType;
        public String name;
        public String changeType;
        public String source;
        public Boolean reviewed;
    }

    // ---------- connection ----------

    @AuraEnabled
    public static RlySettings.Connection getConnection() {
        try {
            return RlySettings.currentConnection();
        } catch (Exception e) {
            throw handled(e);
        }
    }

    /** Every connection (repository) this org can raise from. */
    @AuraEnabled
    public static List<RlySettings.Connection> getConnections() {
        try {
            return RlySettings.connections();
        } catch (Exception e) {
            throw handled(e);
        }
    }

    @AuraEnabled
    public static String testConnection(String target, String connection) {
        try {
            RlySettings.Connection c = RlySettings.connection(connection);
            if (c.isDevOpsCenter) {
                return c.orgLabel + ' releases through DevOps Center. Open it from the link on this page.';
            }
            RlySettings.assertTarget(c, target);
            RlyGitProvider git = RlyGitProvider.forConnection(c);
            List<String> missing = new List<String>();
            if (!git.branchExists(target)) {
                missing.add('target branch ' + target);
            }
            String pipelineFile = pipelineFile(c);
            if (!git.branchExists(c.workflowRef)) {
                missing.add('pipeline branch ' + c.workflowRef);
            } else if (pipelineFile != null && git.getFileRaw(pipelineFile, c.workflowRef) == null) {
                missing.add(pipelineFile + ' on ' + c.workflowRef);
            }
            if (!missing.isEmpty()) {
                throw new AuraHandledException('Connected to ' + c.repository + ', but not found: ' + String.join(missing, ', ') + '.');
            }
            return 'Connected to ' + c.repository + ' (' + c.connectionType + '). ' + c.orgLabel + ' raises ' + c.changeLabel + 's into ' + target + '.';
        } catch (AuraHandledException e) {
            throw e;
        } catch (Exception e) {
            throw handled(e);
        }
    }

    /** Copies connections from the old custom metadata into the Connection object (admins, once). */
    @AuraEnabled
    public static Integer migrateConnections() {
        try {
            if (!RlySettings.isAdmin()) {
                return 0;
            }
            return RlySettings.migrate();
        } catch (Exception e) {
            throw handled(e);
        }
    }

    @AuraEnabled
    public static String saveConnection(String connectionJson) {
        try {
            RlySettings.Connection input =
                (RlySettings.Connection) JSON.deserialize(connectionJson, RlySettings.Connection.class);
            return RlySettings.save(input);
        } catch (Exception e) {
            throw handled(e);
        }
    }

    // ---------- select ----------

    /** Changes in this org. lookbackDays null or 0 means any time. Compared with the target separately (compareChanges). */
    @AuraEnabled
    public static List<RlyChangeService.ChangeItem> getChanges(Integer lookbackDays, String changedBy, String nameSearch, String target, String connection) {
        try {
            RlySettings.Connection c = RlySettings.connection(connection);
            return RlyChangeService.listChanges(c.metadataTypes, lookbackDays, changedBy, nameSearch);
        } catch (Exception e) {
            throw handled(e);
        }
    }

    /**
     * New, Different, Same or Exists for up to 25 changes, compared with the target branch.
     * The page calls this a few items at a time for the rows on screen, so the list shows at once
     * and the comparison fills in as it goes.
     */
    @AuraEnabled
    public static List<RlyChangeService.Comparison> compareChanges(String itemsJson, String target, String connection) {
        try {
            RlySettings.Connection c = RlySettings.connection(connection);
            RlySettings.assertTarget(c, target);
            List<RlyChangeService.ChangeItem> items =
                (List<RlyChangeService.ChangeItem>) JSON.deserialize(itemsJson, List<RlyChangeService.ChangeItem>.class);
            if (items.size() > 25) {
                throw new AuraHandledException('Compare up to 25 items at a time.');
            }
            for (RlyChangeService.ChangeItem i : items) {
                if (String.isBlank(i.metadataType) || !ITEM_TYPE.matcher(i.metadataType).matches() || String.isBlank(i.name) || i.name.length() > 255) {
                    throw new AuraHandledException('"' + i.key + '" isn\'t a valid component.');
                }
            }
            return RlyChangeService.compare(items, RlyGitProvider.forConnection(c), target, c.sourcePath);
        } catch (AuraHandledException e) {
            throw e;
        } catch (Exception e) {
            throw handled(e);
        }
    }

    @AuraEnabled
    public static List<RlyChangeService.ChangeItem> getDeletions(String target, String connection) {
        try {
            RlySettings.Connection c = RlySettings.connection(connection);
            RlySettings.assertTarget(c, target);
            return RlyChangeService.listDeletions(RlyGitProvider.forConnection(c), target, c.sourcePath, c.metadataTypes);
        } catch (Exception e) {
            throw handled(e);
        }
    }

    @AuraEnabled
    public static List<String> getBranches(String connection) {
        try {
            RlySettings.Connection c = RlySettings.connection(connection);
            List<String> out = new List<String>();
            for (String b : RlyGitProvider.forConnection(c).listBranches()) {
                if (RlySettings.BRANCH.matcher(b).matches()) {
                    out.add(b);
                }
            }
            out.sort();
            return out;
        } catch (Exception e) {
            throw handled(e);
        }
    }

    // ---------- review ----------

    @AuraEnabled
    public static List<RlyChangeService.SourceFile> getSources(String metadataType, String componentName, String target, String connection) {
        try {
            RlySettings.Connection c = RlySettings.connection(connection);
            RlySettings.assertTarget(c, target);
            return RlyChangeService.getSources(metadataType, componentName, c.sourcePath, RlyGitProvider.forConnection(c), target);
        } catch (Exception e) {
            throw handled(e);
        }
    }

    @AuraEnabled
    public static RlyGitProvider.Comparison compareBranch(String branch, String target, String connection) {
        try {
            RlySettings.Connection c = RlySettings.connection(connection);
            RlySettings.assertTarget(c, target);
            return RlyGitProvider.forConnection(c).compare(target, branch);
        } catch (Exception e) {
            throw handled(e);
        }
    }

    // ---------- raise ----------

    /**
     * mode 'org': components retrieved from this org (plus deletions) go to a new branch.
     * The release is saved with a pending raise run; the page then calls startPipeline.
     * mode 'branch': a pull request is opened from a branch already in GitHub.
     */
    @AuraEnabled
    public static Id raiseRequest(String mode, String title, String description, String branchName,
                                  String target, String itemsJson, String connection) {
        RlySettings.Connection c;
        try {
            c = RlySettings.connection(connection);
            RlySettings.assertTarget(c, target);
        } catch (Exception e) {
            throw handled(e);
        }
        if (c.isDevOpsCenter) {
            throw new AuraHandledException('Releases for ' + c.label + ' run in DevOps Center. Open it from the link on this page.');
        }
        if (mode != 'org' && mode != 'branch') {
            throw new AuraHandledException('Choose org changes or an existing branch.');
        }
        if (String.isBlank(title) || title.trim().length() > 200) {
            throw new AuraHandledException('Enter a title of up to 200 characters.');
        }
        if (String.isBlank(branchName) || !RlySettings.BRANCH.matcher(branchName).matches()) {
            throw new AuraHandledException('Branch must look like feature/short-name (or bugfix/, hotfix/), using lowercase letters, numbers, dots and dashes.');
        }
        if (branchName != null && branchName == target) {
            throw new AuraHandledException('Source and target branch can\'t be the same.');
        }

        List<ItemInput> items = String.isBlank(itemsJson)
            ? new List<ItemInput>()
            : (List<ItemInput>) JSON.deserialize(itemsJson, List<ItemInput>.class);
        Integer inputChars = 0;
        Integer deletions = 0;
        Integer changes = 0;
        if (mode == 'org') {
            if (items.isEmpty()) {
                throw new AuraHandledException('Select at least one component.');
            }
            for (ItemInput i : items) {
                if (String.isBlank(i.metadataType) || !ITEM_TYPE.matcher(i.metadataType).matches()
                        || String.isBlank(i.name) || i.name.length() > 255 || i.name.containsAny(',\r\n:')) {
                    throw new AuraHandledException('"' + i.metadataType + ':' + i.name + '" isn\'t a valid component.');
                }
                if (!CHANGE_TYPES.contains(i.changeType)) {
                    i.changeType = 'Modified';
                }
                if (i.reviewed != true) {
                    throw new AuraHandledException('Mark ' + i.name + ' as reviewed before raising the pull request.');
                }
                inputChars += i.metadataType.length() + i.name.length() + 2;
                if (i.changeType == 'Deleted') {
                    deletions++;
                } else {
                    changes++;
                }
            }
            if (inputChars > MAX_INPUT_CHARS) {
                throw new AuraHandledException('Too many components for one pull request. Split them into two requests.');
            }
        }

        Data data = new Data();
        if (branchName != null && data.openRequestExists(branchName)) {
            throw new AuraHandledException('An open release already uses branch ' + branchName + '.');
        }
        if (c.isGit) {
            try {
                Boolean exists = RlyGitProvider.forConnection(c).branchExists(branchName);
                if (mode == 'org' && exists) {
                    throw new AuraHandledException('Branch ' + branchName + ' already exists in ' + c.connectionType + '. Pick a new name, or choose "An existing branch".');
                }
                if (mode == 'branch' && !exists) {
                    throw new AuraHandledException('Branch ' + branchName + ' wasn\'t found in ' + c.connectionType + '.');
                }
            } catch (AuraHandledException e) {
                throw e;
            } catch (Exception e) {
                throw handled(e);
            }
        }

        RLY_Release__c req = new RLY_Release__c(
            Title__c = title.trim(),
            Description__c = description == null ? null : description.left(5000),
            Mode__c = mode == 'org' ? 'Org changes' : 'Existing branch',
            Org_Label__c = c.orgLabel,
            Connection__c = c.settingName,
            Connection_Type__c = c.connectionType,
            Target_Environment__c = c.deployEnvironmentFor(target),
            Checks_Requested__c = Datetime.now(),
            Scan_Status__c = c.codeScan == false ? 'Not configured' : 'Pending',
            Validation_Status__c = String.isBlank(c.deployEnvironmentFor(target)) ? 'Not configured' : 'Pending',
            Deploy_Status__c = String.isBlank(c.deployEnvironmentFor(target)) ? 'Not configured' : 'Pending',
            Source_Branch__c = branchName,
            Target_Branch__c = target,
            Deletion_Count__c = deletions,
            Component_Count__c = changes,
            Request_Type__c = requestType(mode, changes, deletions),
            Status__c = 'Submitted',
            Pending_Run__c = RlyPipeline.RAISE_MODE
        );
        insert req;

        List<RLY_Release_Item__c> rows = new List<RLY_Release_Item__c>();
        for (ItemInput i : (mode == 'org' ? items : new List<ItemInput>())) {
            rows.add(new RLY_Release_Item__c(
                Release__c = req.Id,
                Metadata_Type__c = i.metadataType,
                Component_Name__c = i.name,
                Change_Type__c = i.changeType,
                Source__c = i.source == 'Manual' ? 'Manual' : 'Detected',
                Reviewed__c = true,
                Reviewed_On__c = Datetime.now()
            ));
        }
        if (!rows.isEmpty()) {
            insert rows;
        }

        // Callouts can't follow DML in one transaction: the page starts the pipeline next (startPipeline).
        return req.Id;
    }

    /**
     * Starts the release's pending pipeline run (after raise, approve, re-run or sync back).
     * Safe to call any time: it does nothing when no run is pending.
     */
    @AuraEnabled
    public static RLY_Release__c startPipeline(Id requestId) {
        try {
            return RlyPipeline.start(requestId);
        } catch (Exception e) {
            throw handled(e);
        }
    }

    // ---------- history ----------

    @AuraEnabled
    public static List<RLY_Release__c> getRequests(String view) {
        return new Data().requests(view);
    }

    @AuraEnabled
    public static List<RLY_Release_Item__c> getItems(Id requestId) {
        return new Data().items(requestId);
    }

    @AuraEnabled
    public static RLY_Release__c refreshRequest(Id requestId) {
        Data data = new Data();
        List<RLY_Release__c> reqs = data.requestsById(new Set<Id>{ requestId });
        if (reqs.isEmpty()) {
            throw new AuraHandledException('Request not found.');
        }
        RlySyncJob.syncAndSave(reqs);
        return data.requestsById(new Set<Id>{ requestId })[0];
    }

    // ---------- helpers ----------

    /** The pipeline file to look for in the repository, or null when the provider names it otherwise. */
    @TestVisible
    private static String pipelineFile(RlySettings.Connection c) {
        if (c.connectionType == RlySettings.GITHUB) {
            return '.github/workflows/' + c.workflowFile;
        }
        if (c.connectionType == RlySettings.GITLAB) {
            return String.isBlank(c.workflowFile) ? '.gitlab-ci.yml' : c.workflowFile;
        }
        if (c.connectionType == RlySettings.BITBUCKET) {
            return 'bitbucket-pipelines.yml';
        }
        return null;
    }

    /** Changes, Destructive, Changes and destructive, or Manual PR. */
    @TestVisible
    private static String requestType(String mode, Integer changes, Integer deletions) {
        if (mode == 'branch') {
            return 'Manual PR';
        }
        if (deletions > 0) {
            return changes > 0 ? 'Changes and destructive' : 'Destructive';
        }
        return 'Changes';
    }

    private static AuraHandledException handled(Exception e) {
        AuraHandledException ex = new AuraHandledException(e.getMessage());
        ex.setMessage(e.getMessage());
        return ex;
    }

    /** Team-wide history and the duplicate-branch check must see every request. */
    private without sharing class Data {

        public Boolean openRequestExists(String branch) {
            return ![SELECT Id FROM RLY_Release__c
                     WHERE Source_Branch__c = :branch AND Status__c IN :OPEN_STATUSES LIMIT 1].isEmpty();
        }

        public List<RLY_Release__c> requests(String view) {
            Id me = UserInfo.getUserId();
            Datetime monthStart = Datetime.newInstance(Date.today().toStartOfMonth(), Time.newInstance(0, 0, 0, 0));
            List<RLY_Release__c> all = [
                SELECT Id, Name, Title__c, Mode__c, Request_Type__c, Component_Count__c, Org_Label__c, Status__c, Source_Branch__c, Target_Branch__c,
                       PR_Number__c, PR_URL__c, Run_URL__c, Deletion_Count__c, Error_Message__c, Last_Synced__c,
                       Scan_Status__c, Validation_Status__c, Approval_Status__c, Deploy_Status__c, Connection__c, Connection_Type__c,
                       Pending_Run__c, CreatedById, CreatedBy.Name, CreatedDate, LastModifiedDate
                FROM RLY_Release__c ORDER BY CreatedDate DESC LIMIT 500];
            List<RLY_Release__c> out = new List<RLY_Release__c>();
            for (RLY_Release__c r : all) {
                Boolean keep = view == 'mine' ? r.CreatedById == me
                    : view == 'open' ? OPEN_STATUSES.contains(r.Status__c)
                    : view == 'merged' ? ((r.Status__c == 'Merged' || r.Status__c == 'Deployed') && r.LastModifiedDate >= monthStart)
                    : view == 'failed' ? FAILED_STATUSES.contains(r.Status__c)
                    : view == 'approval' ? r.Status__c == 'Ready for approval'
                    : true;
                if (keep && out.size() < 200) {
                    out.add(r);
                }
            }
            return out;
        }

        public List<RLY_Release__c> requestsById(Set<Id> ids) {
            return [SELECT Id, Name, Title__c, Mode__c, Request_Type__c, Component_Count__c, Org_Label__c, Status__c, Source_Branch__c, Target_Branch__c,
                           PR_Number__c, PR_URL__c, Run_ID__c, Run_URL__c, Deletion_Count__c, Error_Message__c,
                           Last_Synced__c, CreatedBy.Name, CreatedDate, Connection__c, Target_Environment__c, Checks_Requested__c,
                           Scan_Status__c, Scan_Violations__c, Scan_Blocking__c, Scan_Result__c,
                           Validation_Status__c, Validation_Result__c, Approval_Status__c, Approved_On__c,
                           Merge_Commit__c, Deploy_Status__c, Deploy_Result__c, Connection_Type__c,
                           Source_Environment__c, Pending_Run__c
                    FROM RLY_Release__c WHERE Id IN :ids];
        }

        public List<RLY_Release_Item__c> items(Id requestId) {
            return [SELECT Id, Name, Metadata_Type__c, Component_Name__c, Change_Type__c, Source__c, Reviewed__c, Reviewed_On__c
                    FROM RLY_Release_Item__c WHERE Release__c = :requestId ORDER BY Name];
        }

        public void save(List<RLY_Release__c> reqs) {
            if (!reqs.isEmpty()) {
                update reqs;
            }
        }
    }
}
